-- Demo commerce data (proposal 7.2). Generated by scripts/gen_commerce_seed.py: do not edit by hand.
-- Runs only with the "demo" profile. Needs the catalog seed (products and variants) to have a lower version.

-- ---------------------------------------------------------------- vouchers

-- ------------------------------------------------------------------ users

-- ------------------------------------------------------------------ orders

-- ------------------------------------------------------- order lines (about 90)

-- orders that found no variant to buy are removed again (their history is not created yet)
delete o from orders o left join order_items i on i.order_id = o.id where o.idempotency_key like 'seed-order-%' and i.id is null;

-- a voucher stays on an order only when the order reached its minimum amount
update orders o join (select order_id, sum(quantity * unit_price) subtotal from order_items group by order_id) s on s.order_id = o.id join vouchers v on v.id = o.voucher_id set o.voucher_id = null where o.idempotency_key like 'seed-order-%' and s.subtotal < v.min_order_amount;

-- money: the same rules as the application (proposal 6.3)
update orders o join (select order_id, sum(quantity * unit_price) subtotal from order_items group by order_id) s on s.order_id = o.id left join vouchers v on v.id = o.voucher_id set o.discount_amount = case when v.type = 'PERCENT' then least(round(s.subtotal * v.discount_value / 100, 2), coalesce(v.max_discount_amount, s.subtotal), s.subtotal) when v.type = 'FIXED_AMOUNT' then least(v.discount_value, s.subtotal) else 0 end, o.shipping_discount = case when v.type = 'FREESHIP' then least(case when v.discount_value = 0 then 30000 else v.discount_value end, 30000) else 0 end where o.idempotency_key like 'seed-order-%';
update orders o join (select order_id, sum(quantity * unit_price) subtotal from order_items group by order_id) s on s.order_id = o.id set o.total_amount = s.subtotal - o.discount_amount + o.shipping_fee - o.shipping_discount where o.idempotency_key like 'seed-order-%';

-- ------------------------------------------------------ status history

-- ---------------------------------------------------- voucher use counts
update vouchers v set v.used_count = (select count(*) from voucher_usages u where u.voucher_id = v.id) where v.created_by = 'seed';
