insert into order_items (order_id, product_variant_id, quantity, unit_price) select o.id, v.id, 2, p.base_price from orders o join (select id, product_id from (select id, product_id, row_number() over (order by id) rn from product_variants) t where rn = 1 + mod(7, nullif((select count(*) from product_variants), 0))) v join products p on p.id = v.product_id where o.idempotency_key = 'seed-order-01';
